        feed_slides: row.feed_slides,
        hook_options: row.hook_options,
        score: row.score,
        scene_json: row.scene_json,
        scene_number: scene.scene || (index + 1),
        scene_index: index,
        scene_duration: Number(scene.duration || 1),
        scene_caption: String(scene.caption || ''),
        image_prompt: String(
          scene.image_prompt || row.cover_prompt || row.final_title || 'news concept'
        ),
